public static boolean pausePotionEffects(LivingEntity entity, MobEffectInstance instance) {
        if (instance.getEffect().equals(MalumMobEffects.GLEEFUL_TARGET)) {
            return false;
        }
        var gleefulTarget = entity.getEffect(MalumMobEffects.GLEEFUL_TARGET);
        if (gleefulTarget != null) {
            MobEffect type = instance.getEffect().value();
            return !type.isInstantenous();
        }
        return false;
    }

@Inject(method = "tick", at = @At("HEAD"))
    private void malum$cacheEntity(LivingEntity entity, Runnable onExpirationRunnable, CallbackInfoReturnable<Boolean> cir) {
        if (entity != null) {
            MobEffectInstance instance = (MobEffectInstance) (Object) this;
            if (malum$isGleefulTargetActive) {
                // Check for Gleeful Target less frequently if it's already active
                if (entity.level().getGameTime() % 10 != 0) {
                    return;
